const RATIO_PROPORTION_SOURCE = {"subject":"Quantitative Aptitude / Mathematics","topic_name":"ગુણોત્તર અને પ્રમાણ (Ratio and Proportion - Complete 100% Lecture 1 & Lecture 2 Data)","total_questions_count":105,"concept_notes":[{"topic":"ગુણોત્તર (Ratio)","definition":"સમાન એકમ ધરાવતા બે કે તેથી વધુ જથ્થાની ભાગાકાર દ્વારા કરવામાં આવતી સરખામણીને ગુણોત્તર કહેવાય છે.","key_rules":["ગુણોત્તરને કોઈ એકમ (unit) હોતો નથી.","ગુણોત્તર શોધતા પહેલા બંને રાશીઓના એકમો સમાન હોવા ફરજિયાત છે (દા.ત. મીટર અને સેન્ટીમીટર હોય તો બંનેને સેન્ટીમીટરમાં ફેરવવા).","ગુણોત્તર હંમેશાં તેના અતિસંક્ષિપ્ત સ્વરૂપમાં દર્શાવાય છે."]},{"topic":"પ્રમાણ (Proportion)","definition":"જ્યારે બે ગુણોત્તરો સમાન હોય ત્યારે તેઓ પ્રમાણમાં છે તેમ કહેવાય (a : b :: c : d અથવા a/b = c/d).","key_formulas":["મૂળભૂત નિયમ: પ્રત્યંત પદોનો ગુણાકાર = મધ્યમ પદોનો ગુણાકાર (a × d = b × c).","મધ્યમ પ્રમાણપદ (Mean Proportional): b = √(a × c)","તૃતીય પ્રમાણપદ (Third Proportional): c = b² / a","ચતુર્થ પ્રમાણપદ (Fourth Proportional): d = (b × c) / a"]},{"topic":"યુટ્યુબ શોર્ટકટ ટ્રીક્સ (YouTube Shortcuts & Methods)","techniques":["Zig-Zag / N-પદ્ધતિ: a:b અને b:c આપેલ હોય ત્યારે a:b:c શોધવા માટે ક્રોસ ગુણાકાર કરવો.","અચળ ઘટક સરખામણી: મિશ્રણમાં જે ઘટક ન ઉમેરાય તેને અચળ રાખી ગુણોત્તર સમાન બનાવવો.","ક્રોસ મલ્ટિપ્લિકેશન ટ્રીક (આવક-ખર્ચ-બચત): (a/b) અને (c/d) વચ્ચે ક્રોસ ગુણાકાર કરીને બચત સાથે સરખાવી x મેળવવો.","સિક્કાના કોયડા (Coins): સિક્કાની સંખ્યા = મૂલ્ય / મૂલ્યવર્ગ (Denomination)."]}],"questions":[{"question_number":1,"question_text":"3.5 m થી 10 cm નો ગુણોત્તર કેટલો છે? (CCE 2023)","options":{"A":"15:9","B":"35:1","C":"20:1","D":"10:3"},"correct_answer":"B","explanation":"ગુણોત્તર મેળવવા માટે બંને જથ્થાના એકમો સમાન હોવા જોઈએ.\n3.5 m = 3.5 × 100 cm = 350 cm.\nહવે ગુણોત્તર = 350 cm / 10 cm = 35 / 1 = 35:1."},{"question_number":2,"question_text":"0.02 અને 0.98 વચ્ચેનું મધ્યમ પ્રમાણપદ શોધો. (CCE 2023)","options":{"A":"0.14","B":"0.16","C":"0.12","D":"0.18"},"correct_answer":"A","explanation":"મધ્યમ પ્રમાણપદ b = √(a × c) = √(0.02 × 0.98) = √(0.0196) = 0.14."},{"question_number":3,"question_text":"196 અને 400 નું મધ્યમ પ્રમાણપદ શોધો. (CCE 2023)","options":{"A":"320","B":"280","C":"254","D":"212"},"correct_answer":"B","explanation":"મધ્યમ પ્રમાણપદ = √(196 × 400) = √196 × √400 = 14 × 20 = 280."},{"question_number":4,"question_text":"જો 192 : y :: y : 48, અને y > 0 હોય, તો y નું મૂલ્ય શોધો. (CCE 2023)","options":{"A":"72","B":"64","C":"96","D":"108"},"correct_answer":"C","explanation":"પ્રમાણના ગુણધર્મ મુજબ y² = 192 × 48.\ny = √(192 × 48) = √(64 × 3 × 16 × 3) = √(64 × 16 × 9) = 8 × 4 × 3 = 96."},{"question_number":5,"question_text":"જો x અને y વચ્ચેનું મધ્યમ પ્રમાણપદ 9 હોય, તો અનુક્રમે x અને y ના 2 સંભવિત મૂલ્યો શું હોઈ શકે? (CCE 2023)","options":{"A":"3, 3","B":"30, 3","C":"27, 3","D":"18, 3"},"correct_answer":"C","explanation":"મધ્યમ પ્રમાણપદ = √(x × y) = 9 ⟹ x × y = 81.\nવિકલ્પોમાંથી (C) 27 × 3 = 81 થાય છે."},{"question_number":6,"question_text":"1/6 અને 1/24 નું ત્રીજું પ્રમાણ શું છે? (CCE 2023)","options":{"A":"1/96","B":"1/75","C":"1/50","D":"1/69"},"correct_answer":"A","explanation":"તૃતીય પ્રમાણપદ c = b² / a = (1/24)² / (1/6) = (1/576) × 6 = 1/96."},{"question_number":7,"question_text":"15, 18 અને 45 નું ચતુર્થ પ્રમાણપદ શોધો. (CCE 2023)","options":{"A":"54","B":"64","C":"72","D":"84"},"correct_answer":"A","explanation":"ચતુર્થ પ્રમાણપદ d = (b × c) / a = (18 × 45) / 15 = 18 × 3 = 54."},{"question_number":8,"question_text":"સંખ્યાઓ 7, 14 અને 28 નું ચતુર્થ પ્રમાણપદ શોધો. (CCE 2023)","options":{"A":"84","B":"72","C":"64","D":"56"},"correct_answer":"D","explanation":"ચતુર્થ પ્રમાણપદ d = (b × c) / a = (14 × 28) / 7 = 2 × 28 = 56."},{"question_number":9,"question_text":"16, 21 અને 8 નું ચતુર્થ પ્રમાણપદ શોધો. (CCE 2023)","options":{"A":"10.5","B":"9.4","C":"8.6","D":"11.2"},"correct_answer":"A","explanation":"ચતુર્થ પ્રમાણપદ d = (21 × 8) / 16 = 21 / 2 = 10.5."},{"question_number":10,"question_text":"જો 36, 48, 81 અને y પ્રમાણસર હોય, તો y નું મૂલ્ય શોધો. (CCE 2023)","options":{"A":"108","B":"144","C":"121","D":"96"},"correct_answer":"A","explanation":"36/48 = 81/y ⟹ y = (48 × 81) / 36 = 4 × 27 = 108."},{"question_number":11,"question_text":"3x, x + 5, 5x અને y ક્રમિક પ્રમાણમાં (continued proportion) માં છે, જ્યારે x = 3 હોય ત્યારે y નું મૂલ્ય શોધો. (CCE 2023)","options":{"A":"50/3","B":"20/3","C":"70/3","D":"40/3"},"correct_answer":"D","explanation":"x = 3 મૂકતાં પ્રથમ ત્રણ પદો: 3(3) = 9, 3 + 5 = 8, 5(3) = 15.\nક્રમિક પ્રમાણ માટે: 9 / 8 = 15 / y ⟹ y = (8 × 15) / 9 = 40 / 3."},{"question_number":12,"question_text":"5x, 4x + 5, 5x અને y ક્રમિક પ્રમાણમાં છે, જ્યારે x = 2 હોય ત્યારે y ની કિંમત શોધો. (CCE 2023)","options":{"A":"13/10","B":"10/13","C":"5/4","D":"13.0"},"correct_answer":"D","explanation":"x = 2 મૂકતાં: 5(2) = 10, 4(2)+5 = 13, 5(2) = 10.\n10 / 13 = 10 / y ⟹ y = 13."},{"question_number":13,"question_text":"જો p એ 2, 6 નું ત્રીજું પ્રમાણપદ હોય, તો 6, p, 5 નું ચોથું પ્રમાણપદ શું છે? (CCE 2023)","options":{"A":"21","B":"18","C":"15","D":"12"},"correct_answer":"C","explanation":"પ્રથમ p શોધીએ: p = 6² / 2 = 36 / 2 = 18.\nહવે 6, 18, 5 નું ચોથું પ્રમાણપદ d = (18 × 5) / 6 = 15."},{"question_number":14,"question_text":"√3.75 એ બે સંખ્યાઓ x અને y વચ્ચેનું મધ્યમ પ્રમાણપદ છે. જો y નું મૂલ્ય 1.5 હોય તો x નું મૂલ્ય શોધો. (CCE 2023)","options":{"A":"4.5","B":"2.5","C":"1.5","D":"3.5"},"correct_answer":"B","explanation":"મધ્યમ પ્રમાણપદ = √(x × y) = √3.75 ⟹ x × y = 3.75.\n1.5 × x = 3.75 ⟹ x = 3.75 / 1.5 = 2.5."},{"question_number":15,"question_text":"l અને m નું મધ્યમ પ્રમાણપદ n છે. l²n અને m²n નું મધ્યમ પ્રમાણપદ શું છે? (CCE 2023)","options":{"A":"n²","B":"3n","C":"n³","D":"n"},"correct_answer":"C","explanation":"મધ્યમ પ્રમાણપદ = √(l²n × m²n) = √(l²m² × n²) = lm × n.\nપરંતુ √(l × m) = n ⟹ lm = n².\nમાટે મધ્યમ પ્રમાણપદ = n² × n = n³."},{"question_number":16,"question_text":"જો 8.25 : x :: 3 : 8, તો x બરાબર ____ છે. (CCE 2023)","options":{"A":"30","B":"25","C":"22","D":"15"},"correct_answer":"C","explanation":"8.25 / x = 3 / 8 ⟹ 3x = 8.25 × 8 = 66 ⟹ x = 66 / 3 = 22."},{"question_number":17,"question_text":"જો (8/3) : x :: (12/7) : (6/5) હોય, તો x નું મૂલ્ય શોધો. (CCE 2023)","options":{"A":"9/8","B":"15/13","C":"28/15","D":"5/12"},"correct_answer":"C","explanation":"(8/3) / x = (12/7) / (6/5) ⟹ (8/3) / x = (12/7) × (5/6) = 10/7.\nx = (8/3) × (7/10) = 28/15."},{"question_number":18,"question_text":"જો a : b = 5 : 7 અને b : c = 7 : 4 હોય, તો a : c ___ છે. (CCE 2023)","options":{"A":"5:4","B":"7:4","C":"4:7","D":"5:7"},"correct_answer":"A","explanation":"a:b:c = 5:7:4. માટે a : c = 5 : 4."},{"question_number":19,"question_text":"જો p : q = 11 : 2 અને q : r = 3 : 2 હોય, તો p : q : r નું મૂલ્ય શોધો. (CCE 2023)","options":{"A":"33:6:2","B":"33:6:4","C":"33:6:1","D":"33:4:6"},"correct_answer":"B","explanation":"p:q = 11:2 = 33:6; q:r = 3:2 = 6:4. માટે p : q : r = 33 : 6 : 4."},{"question_number":20,"question_text":"જો M : N = 4 : 9 અને N : P = 12 : 17 તો M : P નું મૂલ્ય શોધો. (CCE 2023)","options":{"A":"16:51","B":"11:15","C":"17:49","D":"12:37"},"correct_answer":"A","explanation":"M / P = (M/N) × (N/P) = (4/9) × (12/17) = (4 × 4) / (3 × 17) = 16 / 51."},{"question_number":21,"question_text":"જો A : B = 7 : 9 અને B : C = 11 : 19 હોય, તો A : C નું મૂલ્ય શોધો. (CCE 2023)","options":{"A":"55:109","B":"77:171","C":"17:31","D":"7:19"},"correct_answer":"B","explanation":"A / C = (7/9) × (11/19) = 77 / 171."},{"question_number":22,"question_text":"જો m : n = 15 : 32, n : o = 16 : 25, અને o : p = 25 : 14 હોય તો m : o શોધો. (CCE 2023)","options":{"A":"1:5","B":"1:7","C":"2:5","D":"3:10"},"correct_answer":"D","explanation":"m / o = (m/n) × (n/o) = (15/32) × (16/25) = (3/2) × (1/5) = 3 / 10."},{"question_number":23,"question_text":"જો a : b = 2 : 3, b : c = 5 : 6 અને c : d = 6 : 7 હોય તો, a : b : c : d શોધો. (CCE 2023)","options":{"A":"12:15:18:27","B":"10:15:18:21","C":"15:18:21:24","D":"10:18:15:24"},"correct_answer":"B","explanation":"a:b = 2:3 = 10:15; b:c = 5:6 = 15:18; c:d = 6:7 = 18:21.\nમાટે a : b : c : d = 10 : 15 : 18 : 21."},{"question_number":24,"question_text":"U : V = 3 : 7 અને V : W = 5 : 7 જો u = 30 હોય, તો w ની કિંમત શું છે? (CCE 2023)","options":{"A":"90","B":"83","C":"98","D":"85"},"correct_answer":"C","explanation":"U : V : W = 15 : 35 : 49.\n15 એકમ = 30 ⟹ 1 એકમ = 2.\nW = 49 એકમ = 49 × 2 = 98."},{"question_number":25,"question_text":"U : V = 5 : 4 અને V : W = 7 : 9 છે. જો u = 105 હોય, તો w નું મૂલ્ય શું છે? (CCE 2023)","options":{"A":"92","B":"108","C":"86","D":"104"},"correct_answer":"B","explanation":"U : V : W = 35 : 28 : 36.\n35 એકમ = 105 ⟹ 1 એકમ = 3.\nW = 36 એકમ = 36 × 3 = 108."},{"question_number":26,"question_text":"જો G : H = 6 : 5 હોય, તો G + H : H નું મૂલ્ય કેટલું છે? (CCE 2023)","options":{"A":"11:5","B":"2.5:6","C":"6:5","D":"5:11"},"correct_answer":"A","explanation":"(G + H) / H = (6 + 5) / 5 = 11 / 5 = 11:5."},{"question_number":27,"question_text":"જો R : S = 5 : 6 અને S : T = 6 : 8 હોય, તો (R + T) : S નું મૂલ્ય કેટલું છે? (CCE 2023)","options":{"A":"8:7","B":"2:1","C":"13:6","D":"11:8"},"correct_answer":"C","explanation":"R = 5, S = 6, T = 8.\n(R + T) : S = (5 + 8) : 6 = 13 : 6."},{"question_number":28,"question_text":"જો P : Q = 5 : 4 અને Q : R = 2 : 9, તો Q : (P + R) નું મૂલ્ય કેટલું હશે? (CCE 2023)","options":{"A":"4:25","B":"5:21","C":"5:23","D":"4:23"},"correct_answer":"D","explanation":"P:Q = 5:4, Q:R = 4:18 ⟹ P:Q:R = 5:4:18.\nQ : (P + R) = 4 : (5 + 18) = 4 : 23."},{"question_number":29,"question_text":"જો X : Y = 11 : 3 અને Y : Z = 2 : 3 હોય, તો (X + Z) : Y નું મૂલ્ય શું છે? (CCE 2023)","options":{"A":"28:9","B":"31:6","C":"15:22","D":"22:15"},"correct_answer":"B","explanation":"X : Y : Z = 22 : 6 : 9.\n(X + Z) : Y = (22 + 9) : 6 = 31 : 6."},{"question_number":30,"question_text":"જો a : b : c = 3 : 5 : 10 છે. તો (a + b + c) : c નો ગુણોત્તર બરાબર ____ (CCE 2023)","options":{"A":"7:5","B":"7:4","C":"12:7","D":"9:5"},"correct_answer":"D","explanation":"(3 + 5 + 10) : 10 = 18 : 10 = 9 : 5."},{"question_number":31,"question_text":"જો M : N = 8 : 5 હોય, તો (M - N) : (M + N) નું મૂલ્ય કેટલું છે? (CCE 2023)","options":{"A":"4:13","B":"13:3","C":"3:14","D":"3:13"},"correct_answer":"D","explanation":"(8 - 5) : (8 + 5) = 3 : 13."},{"question_number":32,"question_text":"જો g : h = 7 : 2 તો (7g + 2h) : (7g - 2h) નું મૂલ્ય શું હશે? (CCE 2023)","options":{"A":"61:41","B":"53:45","C":"31:9","D":"51:31"},"correct_answer":"B","explanation":"7(7) + 2(2) = 49 + 4 = 53.\n7(7) - 2(2) = 49 - 4 = 45.\nમાટે ગુણોત્તર = 53 : 45."},{"question_number":33,"question_text":"જો x : y = 2 : 5 હોય, તો (5x + y) / (5x - y) નું મૂલ્ય કેટલું છે? (CCE 2023)","options":{"A":"2","B":"5","C":"3","D":"4"},"correct_answer":"C","explanation":"(5(2) + 5) / (5(2) - 5) = (10 + 5) / (10 - 5) = 15 / 5 = 3."},{"question_number":34,"question_text":"જો g : h = 3 : 1 હોય, તો (7g + 2h) : (7g - 2h) નું મૂલ્ય કેટલું હશે? (CCE 2023)","options":{"A":"27:25","B":"23:19","C":"31:28","D":"29:27"},"correct_answer":"B","explanation":"7(3) + 2(1) = 23.\n7(3) - 2(1) = 19.\nમાટે ગુણોત્તર = 23 : 19."},{"question_number":35,"question_text":"જો x / y = 3 / 2 હોય, તો (x² + y²) / (x² - y²) મૂલ્ય શોધો. (CCE 2023)","options":{"A":"5/13","B":"15/4","C":"13/5","D":"4/15"},"correct_answer":"C","explanation":"(3² + 2²) / (3² - 2²) = (9 + 4) / (9 - 4) = 13 / 5."},{"question_number":36,"question_text":"જો p : q = 3 : 1 હોય, તો (q² + p²) : (10q² - p²) નું મૂલ્ય કેટલું હશે? (CCE 2023)","options":{"A":"10:1","B":"5:11","C":"1:10","D":"3:10"},"correct_answer":"A","explanation":"(1² + 3²) : (10(1²) - 3²) = (1 + 9) : (10 - 9) = 10 : 1."},{"question_number":37,"question_text":"જો p : q = 4 : 3 હોય, તો (4q² + 4p²) : (2q² - p²) નું મૂલ્ય શું હશે? (CCE 2023)","options":{"A":"50:1","B":"10:3","C":"100:1","D":"5:1"},"correct_answer":"A","explanation":"આપેલ ગુણોત્તર p:q = 4:3 છે. તેથી p = 4k અને q = 3k લઈએ.\nઅંશ = 4q² + 4p² = 4(3²) + 4(4²) = 36 + 64 = 100.\nછેદ = 2q² − p² = 2(3²) − 4² = 18 − 16 = 2.\nગુણોત્તર = 100:2 = 50:1. તેથી સાચો જવાબ A (50:1)."},{"question_number":38,"question_text":"જો m : n : p = 2 : 1 : 3 હોય, તો (m + 4n + p) : (2m + 2n - p) નું મૂલ્ય શું છે? (CCE 2023)","options":{"A":"1:1","B":"4:1","C":"5:2","D":"3:1"},"correct_answer":"D","explanation":"(2 + 4(1) + 3) : (2(2) + 2(1) - 3) = (2 + 4 + 3) : (4 + 2 - 3) = 9 : 3 = 3 : 1."},{"question_number":39,"question_text":"જો x / y = z / a = b / c = 3 / 4 હોય તો (2x + 2z + 4b) : (2y + 2a + 4c) નું મૂલ્ય શું થાય? (CCE 2023)","options":{"A":"4:5","B":"3:5","C":"3:4","D":"6:5"},"correct_answer":"C","explanation":"સમાન અંશ અને છેદના ગુણાંક સરખા હોવાથી ગુણોત્તર મૂળ કિંમત 3 : 4 જ રહે છે."},{"question_number":40,"question_text":"p / q = r / s = t / u = 5 / 9 છે તો (6p + 3r + 9t) : (6q + 3s + 9u) નું મૂલ્ય શું છે? (CCE 2023)","options":{"A":"5:8","B":"9:5","C":"5:9","D":"5:11"},"correct_answer":"C","explanation":"અંશ અને છેદમાં સમાન સહગુણકોનો ઉપયોગ થવાથી ગુણોત્તર 5 : 9 અચળ રહે છે."},{"question_number":41,"question_text":"જો g : h = 5 : 2 અને j : k = 2g : 7h હોય, તો gj : hk નું મૂલ્ય શું છે? (CCE 2023)","options":{"A":"7:18","B":"5:14","C":"25:14","D":"25:13"},"correct_answer":"C","explanation":"j = 2(5) = 10, k = 7(2) = 14.\ngj : hk = (5 × 10) : (2 × 14) = 50 : 28 = 25 : 14."},{"question_number":42,"question_text":"જો 3g = 5h = 9k હોય, તો g : h : k નું મૂલ્ય શોધો. (CCE 2023)","options":{"A":"15:9:5","B":"5:4:8","C":"9:15:5","D":"5:9:15"},"correct_answer":"A","explanation":"3, 5, 9 નો લ.સા.અ. = 45.\ng = 45/3 = 15, h = 45/5 = 9, k = 45/9 = 5.\nમાટે g : h : k = 15 : 9 : 5."},{"question_number":43,"question_text":"જો A : B : C = 5 : 7 : 11 હોય, તો (A/B) : (B/C) : (C/A) ગુણોત્તર કેટલો છે? (CCE 2023)","options":{"A":"275 : 245 : 847","B":"38 : 35 : 121","C":"247 : 35 : 121","D":"24 : 25 : 847"},"correct_answer":"A","explanation":"5/7 : 7/11 : 11/5.\nછેદનો લ.સા.અ. = 385.\n5 × 55 : 7 × 35 : 11 × 77 = 275 : 245 : 847."},{"question_number":44,"question_text":"જો X : Y : Z = 3 : 4 : 8, તો (X/Y) : (Y/Z) : (Z/X) = ? (CCE 2023)","options":{"A":"3:2:32","B":"9:6:32","C":"9:8:64","D":"12:16:96"},"correct_answer":"B","explanation":"3/4 : 4/8 : 8/3 ⟹ 3/4 : 1/2 : 8/3.\nલ.સા.અ. 12 વડે ગુણતાં: 9 : 6 : 32."},{"question_number":45,"question_text":"જો P : Q : R = 3 : 5 : 8 હોય, તો (P/Q) : (Q/R) : (R/P) = ? (CCE 2023)","options":{"A":"34:78:890","B":"56:87:680","C":"24:15:120","D":"72:75:320"},"correct_answer":"D","explanation":"3/5 : 5/8 : 8/3.\nછેદનો લ.સા.અ. = 120.\n3 × 24 : 5 × 15 : 8 × 40 = 72 : 75 : 320."},{"question_number":46,"question_text":"જો (9a + 3b) : (9a - 3b) = 9 : 3 હોય, તો a : b નું મૂલ્ય શું છે? (CCE 2023)","options":{"A":"11:19","B":"5:9","C":"4:13","D":"2:3"},"correct_answer":"D","explanation":"(9a + 3b) / (9a - 3b) = 3 / 1.\n9a + 3b = 27a - 9b ⟹ 12b = 18a ⟹ a / b = 12 / 18 = 2 / 3."},{"question_number":47,"question_text":"જો a : b : c = 3 : 5 : 7 અને 2a - 3b + 5c = 104 હોય, તો c નું મૂલ્ય ______ છે. (CCE 2023)","options":{"A":"28","B":"22","C":"35","D":"32"},"correct_answer":"A","explanation":"a:b:c = 3:5:7 હોવાથી a = 3k, b = 5k, c = 7k.\n2a − 3b + 5c = 104 માં મૂકો: 2(3k) − 3(5k) + 5(7k) = 104.\n6k − 15k + 35k = 104 ⟹ 26k = 104 ⟹ k = 4.\nc = 7k = 7 × 4 = 28. તેથી સાચો જવાબ A (28)."},{"question_number":48,"question_text":"એક વર્ગમાં છોકરાઓ અને છોકરીઓનો ગુણોત્તર 3 : 4 છે. જો વર્ગમાં 21 છોકરાઓ હોય, તો વર્ગમાં કેટલી છોકરીઓ છે? (CCE 2023)","options":{"A":"28","B":"32","C":"14","D":"24"},"correct_answer":"A","explanation":"3 ભાગ = 21 ⟹ 1 ભાગ = 7.\nછોકરીઓ = 4 ભાગ = 4 × 7 = 28."},{"question_number":49,"question_text":"બે ઉમેદવારો P અને Q ના ગુણ, 17 : 19 ના ગુણોત્તરમાં છે. જો P ના ગુણ 170 હોય, તો Q ના ગુણ કેટલા હશે? (CCE 2023)","options":{"A":"180","B":"190","C":"170","D":"160"},"correct_answer":"B","explanation":"17 ભાગ = 170 ⟹ 1 ભાગ = 10.\nQ ના ગુણ = 19 ભાગ = 19 × 10 = 190."},{"question_number":50,"question_text":"એક ટેસ્ટ મેચમાં, વિરાટ અને રોહિતે બનાવેલા રનનો ગુણોત્તર 13 : 15 હતો. જો વિરાટે 195 રન બનાવ્યા હોય, તો રોહિતે બનાવેલા રન શોધો. (CCE 2023)","options":{"A":"205","B":"225","C":"215","D":"235"},"correct_answer":"B","explanation":"13 ભાગ = 195 ⟹ 1 ભાગ = 15.\nરોહિતના રન = 15 ભાગ = 15 × 15 = 225."},{"question_number":51,"question_text":"એલેક્સ અને બોબી તેમના સંગ્રહમાં કાર્ડની સંખ્યાની સરખામણી કરી રહ્યાં છે. એલેક્સ પાસે 120 કાર્ડ છે. એલેક્સ પાસેના કાર્ડની સંખ્યા અને બોબીના કાર્ડની સંખ્યાનો ગુણોત્તર 3 : 4 છે, બોબી પાસે કેટલા કાર્ડ છે? (CCE 2023)","options":{"A":"180","B":"160","C":"90","D":"150"},"correct_answer":"B","explanation":"3 ભાગ = 120 ⟹ 1 ભાગ = 40.\nબોબીના કાર્ડ = 4 ભાગ = 4 × 40 = 160."},{"question_number":52,"question_text":"ત્રણ સંખ્યાઓનો ગુણોત્તર 4 : 1 : 7 છે. જો પ્રથમ સંખ્યાના 25 ટકા 60 છે, તો ત્રીજી અને બીજી સંખ્યાના તફાવતના 20 ટકા શું થશે? (CCE 2023)","options":{"A":"92","B":"62","C":"72","D":"52"},"correct_answer":"C","explanation":"પ્રથમ સંખ્યાના 25% (1/4) = 60 ⟹ પ્રથમ સંખ્યા = 240.\n4 ભાગ = 240 ⟹ 1 ભાગ = 60.\nત્રીજી અને બીજી સંખ્યાનો તફાવત = 7 - 1 = 6 ભાગ.\n6 ભાગ = 6 × 60 = 360.\n360 ના 20% = 360 × (1/5) = 72."},{"question_number":53,"question_text":"45 ને 2 : 3 ના ગુણોત્તરમાં વિભાજિત કરો. (CCE 2023)","options":{"A":"16 અને 29","B":"23 અને 22","C":"18 અને 27","D":"13 અને 32"},"correct_answer":"C","explanation":"કુલ ભાગ = 2 + 3 = 5 ભાગ = 45 ⟹ 1 ભાગ = 9.\nભાગ 1 = 2 × 9 = 18; ભાગ 2 = 3 × 9 = 27."},{"question_number":54,"question_text":"72 ને 4 : 5 ના ગુણોત્તરમાં વિભાજિત કરો. (CCE 2023)","options":{"A":"32 અને 40","B":"28 અને 44","C":"35 અને 37","D":"43 અને 29"},"correct_answer":"A","explanation":"કુલ 9 ભાગ = 72 ⟹ 1 ભાગ = 8.\n4 × 8 = 32 અને 5 × 8 = 40."},{"question_number":55,"question_text":"108 ને 4 : 5 ના ગુણોત્તરમાં વિભાજિત કરો. (CCE 2023)","options":{"A":"40 અને 68","B":"48 અને 60","C":"44 અને 64","D":"36 અને 72"},"correct_answer":"B","explanation":"કુલ 9 ભાગ = 108 ⟹ 1 ભાગ = 12.\n4 × 12 = 48 અને 5 × 12 = 60."},{"question_number":56,"question_text":"112 ને 3 : 5 ના ગુણોત્તરમાં વિભાજિત કરો. (CCE 2023)","options":{"A":"42 અને 70","B":"44 અને 72","C":"46 અને 66","D":"40 અને 72"},"correct_answer":"A","explanation":"કુલ 8 ભાગ = 112 ⟹ 1 ભાગ = 14.\n3 × 14 = 42 અને 5 × 14 = 70."},{"question_number":57,"question_text":"બે સંખ્યાઓ 7 : 8 ના ગુણોત્તરમાં છે. જો સંખ્યાઓનો સરવાળો 180 છે, તો મોટી સંખ્યા કઈ છે? (CCE 2023)","options":{"A":"90","B":"96","C":"78","D":"85"},"correct_answer":"B","explanation":"15 ભાગ = 180 ⟹ 1 ભાગ = 12.\nમોટી સંખ્યા = 8 × 12 = 96."},{"question_number":58,"question_text":"ત્રણ સંખ્યાઓનો ગુણોત્તર 7 : 6 : 5 છે. જો ત્રણ સંખ્યાઓનો સરવાળો 324 છે, તો ત્રણ સંખ્યાઓમાં સૌથી મોટી સંખ્યા કઈ છે? (CCE 2023)","options":{"A":"126","B":"108","C":"90","D":"118"},"correct_answer":"A","explanation":"18 ભાગ = 324 ⟹ 1 ભાગ = 18.\nસૌથી મોટી સંખ્યા = 7 × 18 = 126."},{"question_number":59,"question_text":"ત્રણ સંખ્યાઓનો ગુણોત્તર 7 : 4 : 2 છે. જો ત્રણ સંખ્યાઓનો સરવાળો 208 છે, તો ત્રણ સંખ્યાઓમાં સૌથી મોટી સંખ્યા કઈ છે? (CCE 2023)","options":{"A":"112","B":"105","C":"84","D":"119"},"correct_answer":"A","explanation":"13 ભાગ = 208 ⟹ 1 ભાગ = 16.\nમોટી સંખ્યા = 7 × 16 = 112."},{"question_number":60,"question_text":"ત્રણ સંખ્યાઓનો ગુણોત્તર 7 : 8 : 10 છે. જો ત્રણ સંખ્યાઓનો સરવાળો 400 હોય, તો ત્રણ સંખ્યાઓમાંથી સૌથી નાની સંખ્યા કઈ છે? (CCE 2023)","options":{"A":"126","B":"112","C":"168","D":"84"},"correct_answer":"B","explanation":"25 ભાગ = 400 ⟹ 1 ભાગ = 16.\nનાની સંખ્યા = 7 × 16 = 112."},{"question_number":61,"question_text":"A : B : C નો હિસ્સો 3 : 2 : 5 ના ગુણોત્તરમાં છે. C ને ₹ 1860 માંથી કેટલા પૈસા મળશે? (CCE 2023)","options":{"A":"₹ 620","B":"₹ 660","C":"₹ 840","D":"₹ 930"},"correct_answer":"D","explanation":"કુલ 10 ભાગ = 1860 ⟹ 1 ભાગ = 186.\nC નો હિસ્સો = 5 ભાગ = 5 × 186 = ₹ 930."},{"question_number":62,"question_text":"એક ચોક્કસ પ્રકારના સોદામાં A, B, C ના શેરનું પ્રમાણ 4 : 3 : 5 છે. ₹ 1320 માંથી C ને કેટલા પૈસા મળશે? (CCE 2023)","options":{"A":"₹ 630","B":"₹ 480","C":"₹ 390","D":"₹ 550"},"correct_answer":"D","explanation":"કુલ 12 ભાગ = 1320 ⟹ 1 ભાગ = 110.\nC નો હિસ્સો = 5 × 110 = ₹ 550."},{"question_number":63,"question_text":"Rs. 18500 ને અનુક્રમે 10 : 12 : 15 ના ગુણોત્તરમાં X, Y અને Z વચ્ચે વહેંચવામાં આવે છે. તો Y નો હિસ્સો કેટલો હશે? (CCE 2023)","options":{"A":"Rs. 6500","B":"Rs. 7500","C":"Rs. 6000","D":"Rs. 5000"},"correct_answer":"C","explanation":"કુલ 37 ભાગ = 18500 ⟹ 1 ભાગ = 500.\nY નો હિસ્સો = 12 × 500 = Rs. 6000."},{"question_number":64,"question_text":"રણજીત પાસે Rs. 74880 છે. તે આ રકમ તેમના પુત્ર અને પુત્રી વચ્ચે અનુક્રમે 23 : 25 ના પ્રમાણમાં વહેંચવા માગે છે. તેના પુત્રને મળેલી રકમ શોધો. (CCE 2023)","options":{"A":"Rs. 35880","B":"Rs. 36540","C":"Rs. 37580","D":"Rs. 38420"},"correct_answer":"A","explanation":"કુલ 48 ભાગ = 74880 ⟹ 1 ભાગ = 1560.\nપુત્રનો હિસ્સો = 23 × 1560 = Rs. 35880."},{"question_number":65,"question_text":"ત્રણ સંખ્યાઓનો સરવાળો 261 થાય છે. બીજી અને ત્રીજીનો ગુણોત્તર 9 : 16 છે જ્યારે કે પ્રથમ અને ત્રીજીનો 1 : 4 છે. તો બીજી સંખ્યા શોધો. (CCE 2023)","options":{"A":"78","B":"36","C":"72","D":"81"},"correct_answer":"D","explanation":"પ્રથમ:ત્રીજી = 1:4 = 4:16; બીજી:ત્રીજી = 9:16.\nઅનુક્રમે A:B:C = 4 : 9 : 16.\nકુલ 29 ભાગ = 261 ⟹ 1 ભાગ = 9.\nબીજી સંખ્યા = 9 × 9 = 81."},{"question_number":66,"question_text":"એક વ્યક્તિ મહેશ, નિલેશ અને ઓબલેશ વચ્ચે ₹ 8127 વહેંચે છે. મહેશની રકમ અને નિલેશની રકમનો ગુણોત્તર 4 : 7 છે. અને ઓબલેશની રકમ અને નિલેશની રકમનો ગુણોત્તર 3 : 2 છે. ઓબલેશને કેટલી રકમ મળે છે? (CCE 2023)","options":{"A":"₹ 3611","B":"₹ 3969","C":"₹ 3735","D":"₹ 4010"},"correct_answer":"B","explanation":"મહેશ:નિલેશ = 4:7 = 8:14; નિલેશ:ઓબલેશ = 2:3 = 14:21.\nમહેશ : નિલેશ : ઓબલેશ = 8 : 14 : 21.\nકુલ 43 ભાગ = 8127 ⟹ 1 ભાગ = 189.\nઓબલેશનો હિસ્સો = 21 × 189 = ₹ 3969."},{"question_number":67,"question_text":"જો ₹ 675 A, B અને C વચ્ચે એવી રીતે વહેંચવાના છે કે A ને B ને જે મળે છે તેનો 3/4 ભાગ મળે અને B ને C ને મળે છે તેનો 1/5 ભાગ મળે, B નો હિસ્સો કેટલો છે? (CCE 2023)","options":{"A":"₹ 110","B":"₹ 120","C":"₹ 100","D":"₹ 80"},"correct_answer":"C","explanation":"A = 3/4 B ⟹ A:B = 3:4; B = 1/5 C ⟹ B:C = 1:5 = 4:20.\nA : B : C = 3 : 4 : 20.\nકુલ 27 ભાગ = 675 ⟹ 1 ભાગ = 25.\nB નો હિસ્સો = 4 × 25 = ₹ 100."},{"question_number":68,"question_text":"રઘુ પાસે વિવિધ મૂલ્યવર્ગના ચોક્કસ સંખ્યામાં સિક્કા છે. જો તેની પાસે ₹1 ના સિક્કા અને ₹2 ના સિક્કાની સંખ્યાની ગુણોત્તર અનુક્રમે 5 : 7 છે અને ₹2 ના સિક્કા અને ₹5 ના સિક્કાની સંખ્યાનો ગુણોત્તર અનુક્રમે 7 : 6 છે. જો રઘુ પાસે ₹1 ના સિક્કાનું કુલ મૂલ્ય ₹15 હોય તો ₹5 ના સિક્કાનું કુલ મૂલ્ય શોધો. (CCE 2023)","options":{"A":"Rs. 90","B":"Rs. 45","C":"Rs. 150","D":"Rs. 135"},"correct_answer":"A","explanation":"સિક્કાઓની સંખ્યાનો ગુણોત્તર ₹1 : ₹2 : ₹5 = 5 : 7 : 6.\n₹1 ના સિક્કાનું મૂલ્ય = 5 × 1 = ₹5x = ₹15 ⟹ x = 3.\n₹5 ના સિક્કાઓની સંખ્યા = 6 × 3 = 18.\n₹5 ના સિક્કાનું કુલ મૂલ્ય = 18 × 5 = Rs. 90."},{"question_number":69,"question_text":"એક થેલીમાં સમાન સંખ્યામાં 2 રૂપિયા, 10 રૂપિયા અને 5 રૂપિયાના સિક્કા છે. જો કુલ રકમ Rs. 578 છે, તો દરેક પ્રકારના કેટલા સિક્કા હશે? (CCE 2023)","options":{"A":"36","B":"24","C":"40","D":"34"},"correct_answer":"D","explanation":"દરેક પ્રકારના સિક્કાની સંખ્યા x છે.\nકુલ મૂલ્ય = 2x + 10x + 5x = 17x = 578 ⟹ x = 34."},{"question_number":70,"question_text":"એક શાળામાં કુલ વિદ્યાર્થીઓની સંખ્યા 2400 છે. જો છોકરાઓ અને છોકરીઓનો ગુણોત્તર 5 : 3 છે, તો વિદ્યાર્થીઓની સંખ્યા વિદ્યાર્થીનીઓ કરતાં કેટલી વધારે છે? (CCE 2023)","options":{"A":"900","B":"300","C":"1500","D":"600"},"correct_answer":"D","explanation":"કુલ 8 ભાગ = 2400 ⟹ 1 ભાગ = 300.\nછોકરાઓ અને છોકરીઓનો તફાવત = 5 - 3 = 2 ભાગ.\n2 × 300 = 600."},{"question_number":71,"question_text":"A અને B પાસે કુલ મળીને ₹ 1245 છે. જો A ની રકમના 4/15 B ની રકમના 2/5 ના બરાબર છે, તો B પાસે કેટલી રકમ છે? (CCE 2023)","options":{"A":"₹ 598","B":"₹ 548","C":"₹ 638","D":"₹ 498"},"correct_answer":"D","explanation":"(4/15) A = (2/5) B ⟹ A / B = (2/5) × (15/4) = 3 / 2.\nA : B = 3 : 2.\nકુલ 5 ભાગ = 1245 ⟹ 1 ભાગ = 249.\nB પાસેની રકમ = 2 × 249 = ₹ 498."},{"question_number":72,"question_text":"ત્રણ વસ્તુઓની સરેરાશ કિંમત ₹ 13,160 છે. જો તેમની કિંમતો 6 : 7 : 11 ગુણોત્તરમાં હોય, તો સૌથી મોંઘી વસ્તુની કિંમત _______ છે. (CCE 2023)","options":{"A":"₹ 16,450","B":"₹ 19,290","C":"₹ 18,095","D":"₹ 15,195"},"correct_answer":"C","explanation":"કુલ કિંમત = 13,160 × 3 = 39,480.\nકુલ 24 ભાગ = 39480 ⟹ 1 ભાગ = 1645.\nસૌથી મોંઘી વસ્તુ = 11 ભાગ = 11 × 1645 = ₹ 18,095."},{"question_number":73,"question_text":"કોઈ ત્રણ સંખ્યાઓ 4 : 5 : 10 ના ગુણોત્તરમાં છે. જો સૌથી મોટી અને સૌથી નાની સંખ્યાઓનો સરવાળો 9800 છે, તો સૌથી મોટી અને સૌથી નાની સંખ્યાઓ વચ્ચેનો તફાવત શું છે? (CCE 2023)","options":{"A":"2800","B":"4200","C":"3500","D":"2100"},"correct_answer":"B","explanation":"સૌથી મોટી (10) + સૌથી નાની (4) = 14 ભાગ = 9800 ⟹ 1 ભાગ = 700.\nતફાવત = 10 - 4 = 6 ભાગ = 6 × 700 = 4200."},{"question_number":74,"question_text":"Rs. 900ની કુલ રકમ P, Q અને R વચ્ચે વહેંચવામાં આવી છે. જો તેઓમાંથી દરેકને Rs. 60 ઓછા મળ્યા હોત, તો તેઓના હિસ્સા અનુક્રમે 4 : 3 : 2 ના ગુણોત્તરમાં હોત. તો R ને મળતી રકમ કેટલી છે? (CCE 2023)","options":{"A":"Rs. 180","B":"Rs. 220","C":"Rs. 150","D":"Rs. 300"},"correct_answer":"B","explanation":"ઘટાડેલી કુલ રકમ = 900 - (3 × 60) = 900 - 180 = 720.\nકુલ 9 ભાગ = 720 ⟹ 1 ભાગ = 80.\nR નો ઘટાડેલો હિસ્સો = 2 × 80 = 160.\nR ની મૂળ રકમ = 160 + 60 = Rs. 220."},{"question_number":75,"question_text":"Rs. 600ની રકમ A, B અને C વચ્ચે વહેંચવામાં આવી હતી. જો તેમાંથી દરેકને Rs. 40 ઓછા મળ્યા હોત, તો તેમનો હિસ્સો 3 : 2 : 1 ના ગુણોત્તરમાં હોત. તો મૂળરૂપે C દ્વારા પ્રાપ્ત થયેલ નાણાં _______ હતા. (CCE 2023)","options":{"A":"Rs. 100","B":"Rs. 200","C":"Rs. 120","D":"Rs. 40"},"correct_answer":"C","explanation":"ઘટાડેલી કુલ રકમ = 600 - 120 = 480.\n6 ભાગ = 480 ⟹ 1 ભાગ = 80.\nC નો ઘટાડેલો હિસ્સો = 1 ભાગ = 80.\nC ની મૂળ રકમ = 80 + 40 = Rs. 120."},{"question_number":76,"question_text":"Rs. 560 ની રકમ X, Y અને Z વચ્ચે વહેંચવામાં આવી હતી. જો તેમાંથી દરેકને Rs. 20 ઓછા મળ્યા હોત, તો તેમના હિસ્સાનો ગુણોત્તર 1 : 1 : 2 હોત. તો Z દ્વારા પ્રાપ્ત થયેલા નાણાં કેટલા હતા? (CCE 2023)","options":{"A":"Rs. 125","B":"Rs. 200","C":"Rs. 175","D":"Rs. 270"},"correct_answer":"D","explanation":"ઘટાડેલી કુલ રકમ = 560 - 60 = 500.\n4 ભાગ = 500 ⟹ 1 ભાગ = 125.\nZ નો ઘટાડેલો હિસ્સો = 2 ભાગ = 250.\nZ ની મૂળ રકમ = 250 + 20 = Rs. 270."},{"question_number":77,"question_text":"Rs. 2542 ની રકમને P, Q અને R વચ્ચે એવી રીતે વિભાજિત કરવામાં આવી છે, કે જો P, Q અને R ના હિસ્સામાંથી અનુક્રમે Rs. 13, Rs. 19 અને Rs. 14 ઘટાડવામાં આવે, તો તેમનો હિસ્સો 17 : 16 : 15 ના ગુણોત્તરમાં હશે. તો R નો પ્રારંભિક હિસ્સો કેટલો હશે? (CCE 2023)","options":{"A":"Rs. 720","B":"Rs. 794","C":"Rs. 780","D":"Rs. 660"},"correct_answer":"B","explanation":"કુલ ઘટાડો = 13 + 19 + 14 = 46.\nઘટાડેલી રકમ = 2542 - 46 = 2496.\nકુલ 48 ભાગ = 2496 ⟹ 1 ભાગ = 52.\nR નો ઘટાડેલો હિસ્સો = 15 × 52 = 780.\nR નો મૂળ હિસ્સો = 780 + 14 = Rs. 794."},{"question_number":78,"question_text":"Rs. 2677 ની રકમ P, Q અને R વચ્ચે એવી રીતે વિભાજિત કરવામાં આવી છે કે જો P, Q અને R ના હિસ્સામાંથી અનુક્રમે Rs. 18, Rs. 17 અને Rs. 10 ઘટાડવામાં આવે તો, તેમનો હિસ્સો 17 : 16 : 14 ના ગુણોત્તરમાં હશે. તો R નો પ્રારંભિક હિસ્સો કેટલો હશે? (CCE 2023)","options":{"A":"Rs. 750","B":"Rs. 794","C":"Rs. 780","D":"Rs. 792"},"correct_answer":"B","explanation":"કુલ ઘટાડો = 18 + 17 + 10 = 45.\nઘટાડેલી રકમ = 2677 - 45 = 2632.\nકુલ 47 ભાગ = 2632 ⟹ 1 ભાગ = 56.\nR નો ઘટાડેલો હિસ્સો = 14 × 56 = 784.\nR નો પ્રારંભિક હિસ્સો = 784 + 10 = Rs. 794."},{"question_number":79,"question_text":"એક સ્પર્ધામાં, ₹200,000 ની ઇનામની રકમ ત્રણ સ્પર્ધકો A, B અને C વચ્ચે અનુક્રમે 3 : 2 : 5 ના ગુણોત્તર અનુસાર વહેંચવાની છે. સ્પર્ધક B તેના ઇનામનો એક ભાગ દાન આપવાનું નક્કી કરે છે. જો તે તેની ઇનામની રકમના 8 ભાગોમાંથી 2 ભાગ દાન કરે તો તેની પાસે કેટલી રકમ બાકી રહેશે? (CCE 2023)","options":{"A":"₹ 30,000","B":"₹ 40,000","C":"₹ 50,000","D":"₹ 60,000"},"correct_answer":"A","explanation":"કુલ 10 ભાગ = 200,000 ⟹ 1 ભાગ = 20,000.\nB ની ઇનામની રકમ = 2 ભાગ = ₹ 40,000.\nદાન = 2/8 (એટલે કે 1/4) ભાગ = 40,000 × (1/4) = ₹ 10,000.\nબાકી રકમ = 40,000 - 10,000 = ₹ 30,000."},{"question_number":80,"question_text":"રાજનો પગાર સેમ કરતાં બે ગણો અને ડ્રેક કરતાં પાંચ ગણો છે. જો તેમની કુલ કમાણી ₹34,000 છે, તો રાજની કમાણી શોધો. (CCE 2023)","options":{"A":"₹ 20000","B":"₹ 12000","C":"₹ 24000","D":"₹ 18000"},"correct_answer":"A","explanation":"R = 2S = 5D ⟹ R : S : D = 10 : 5 : 2.\nકુલ 17 ભાગ = 34000 ⟹ 1 ભાગ = 2000.\nરાજની કમાણી = 10 ભાગ = 10 × 2000 = ₹ 20,000."},{"question_number":81,"question_text":"બે સંખ્યાઓનો ગુણોત્તર 4 : 9 છે. જો તેમનો તફાવત 675 છે, તો સૌથી નાની સંખ્યા કઈ છે? (CCE 2023)","options":{"A":"435","B":"675","C":"1215","D":"540"},"correct_answer":"D","explanation":"તફાવત = 9 - 4 = 5 ભાગ = 675 ⟹ 1 ભાગ = 135.\nનાની સંખ્યા = 4 × 135 = 540."},{"question_number":82,"question_text":"જો બે ધન સંખ્યાઓનો ગુણોત્તર 11 : 15 છે અને તેમનો ગુણાકાર 660 છે, તો સંખ્યાઓનો તફાવત _______ છે. (CCE 2023)","options":{"A":"8","B":"11","C":"5","D":"3"},"correct_answer":"A","explanation":"11x × 15x = 660 ⟹ 165x² = 660 ⟹ x² = 4 ⟹ x = 2.\nતફાવત = 15x - 11x = 4x = 4 × 2 = 8."},{"question_number":83,"question_text":"બે સંખ્યાઓનો ગુણોત્તર 7 : 2 છે. જો તેમનો ગુણાકાર 2744 છે, તો બંને સંખ્યાઓનો સરવાળો કેટલો થશે? (CCE 2023)","options":{"A":"126","B":"98","C":"112","D":"70"},"correct_answer":"A","explanation":"7x × 2x = 2744 ⟹ 14x² = 2744 ⟹ x² = 196 ⟹ x = 14.\nસરવાળો = 9x = 9 × 14 = 126."},{"question_number":84,"question_text":"જો ત્રણ સંખ્યાઓ 8 : 6 : 3 ના ગુણોત્તરમાં હોય અને તેમના વર્ગોનો સરવાળો 981 છે, તો સૌથી મોટી અને સૌથી નાની સંખ્યા વચ્ચે શું તફાવત છે? (CCE 2023)","options":{"A":"9","B":"6","C":"3","D":"15"},"correct_answer":"D","explanation":"(8x)² + (6x)² + (3x)² = 981 ⟹ 64x² + 36x² + 9x² = 981 ⟹ 109x² = 981 ⟹ x² = 9 ⟹ x = 3.\nતફાવત = 8x - 3x = 5x = 5 × 3 = 15."},{"question_number":85,"question_text":"બે સંખ્યાઓનો સરવાળો 102 છે અને તેમનો તફાવત 34 છે. તો બે સંખ્યાઓનો ગુણોત્તર કેટલો હશે? (CCE 2023)","options":{"A":"4:1","B":"5:2","C":"3:1","D":"2:1"},"correct_answer":"D","explanation":"a = (102 + 34)/2 = 68, b = (102 - 34)/2 = 34.\na : b = 68 : 34 = 2 : 1."},{"question_number":86,"question_text":"બે ધન પૂર્ણાંકોનો સરવાળો 26 છે અને તેમનો તફાવત 6 છે. તેમનો ગુણાકાર શોધો. (CCE 2023)","options":{"A":"180","B":"135","C":"160","D":"145"},"correct_answer":"C","explanation":"મોટી સંખ્યા = (26 + 6)/2 = 16; નાની સંખ્યા = (26 - 6)/2 = 10.\nગુણાકાર = 16 × 10 = 160."},{"question_number":87,"question_text":"2 : 5 ના દરેક પદમાં કેટલા ઉમેરવા જોઈએ કે જેથી તે 3 : 4 બને? (CCE 2023)","options":{"A":"16","B":"7","C":"5","D":"12"},"correct_answer":"B","explanation":"(2 + x) / (5 + x) = 3 / 4 ⟹ 8 + 4x = 15 + 3x ⟹ x = 7."},{"question_number":88,"question_text":"વિકાસે 3 પરીક્ષાઓ આપી હતી. ત્રણ પરીક્ષાઓમાં તેણે મેળવેલા ગુણોનો સંબંધિત ગુણોત્તર 4 : 3 : 6 છે. 3 પરીક્ષાના મહત્તમ ગુણોનો સંબંધિત ગુણોત્તર 8 : 8 : 7 છે. જો તેણે કુલ 50 ટકા ગુણ મેળવ્યા હોય, તો કેટલી પરીક્ષામાં તેણે 50 ટકાથી વધુ ગુણ મેળવ્યા હોય? (CCE 2023)","options":{"A":"3","B":"1","C":"2","D":"0"},"correct_answer":"B","explanation":"મેળવેલા ગુણ = 4k, 3k, 6k; મહત્તમ ગુણ = 8m, 8m, 7m.\nટકાવારી 1: 4/8 = 50%; ટકાવારી 2: 3/8 = 37.5%; ટકાવારી 3: 6/7 = 85.7%.\n50% થી વધુ ગુણ માત્ર 1 પરીક્ષામાં મળ્યા છે."},{"question_number":89,"question_text":"સચિન અને રવિ પાસે સાથે મળીને ₹920 છે. રવિ પાસેથી ₹ 200 લીધા બાદ સચિન પાસે એટલી જ રકમ થશે જે પહેલેથી રવિ પાસે હતી. તો રવિ અને સચિન પાસે શરૂઆતમાં જે રકમ હતી એનો ગુણોત્તર શોધો. (CCE 2023)","options":{"A":"9:5","B":"13:9","C":"14:9","D":"17:8"},"correct_answer":"C","explanation":"ધારો કે શરૂઆતમાં સચિન પાસે S અને રવિ પાસે R રૂપિયા છે.\nકુલ રકમ: S + R = 920.\nરવિ પાસેથી ₹200 સચિનને મળે ત્યારે સચિનની રકમ S + 200 થાય છે; પ્રશ્ન મુજબ તે રવિની શરૂઆતની રકમ R જેટલી છે. તેથી S + 200 = R ⟹ R − S = 200.\nબંને સમીકરણથી R = 560 અને S = 360 મળે છે.\nરવિ : સચિન = 560:360 = 14:9. સાચો જવાબ C."},{"question_number":90,"question_text":"અજય અને રાજુ પાસે ભેગી રકમ ₹1060 છે. અજય રાજુને ₹140 આપે પછી અજય પાસે રહેલી રકમ રાજુની શરૂઆતની રકમ જેટલી થાય છે. તો શરૂઆતમાં અજય અને રાજુ પાસે હતી એ રકમોનો ગુણોત્તર શોધો. (CCE 2023)","options":{"A":"46:25","B":"30:23","C":"33:21","D":"39:22"},"correct_answer":"B","explanation":"ધારો કે શરૂઆતમાં અજય પાસે A અને રાજુ પાસે R રૂપિયા છે.\nકુલ રકમ: A + R = 1060.\nઅજય ₹140 આપે પછી તેની પાસે A − 140 રહે છે; આ રકમ રાજુની શરૂઆતની રકમ R જેટલી છે. તેથી A − 140 = R ⟹ A − R = 140.\nહવે A + R = 1060 અને A − R = 140 સરવાળતાં 2A = 1200 ⟹ A = 600.\nR = 1060 − 600 = 460. તેથી A:R = 600:460 = 30:23. સાચો જવાબ B."},{"question_number":91,"question_text":"એક પુસ્તકાલયમાં, વાર્તાના પુસ્તકોની સંખ્યા અને વાર્તા સિવાયના પુસ્તકોની સંખ્યાનો ગુણોત્તર 5 : 4 હતો અને વાર્તાના પુસ્તકોની કુલ સંખ્યા 1200 હતી. જ્યારે થોડાક વધુ વાર્તાઓના પુસ્તકો ખરીદવામાં આવ્યા હતા, ત્યારે ગુણોત્તર 3 : 2 થયો હતો. ખરીદેલા વાર્તાના પુસ્તકોની સંખ્યા શોધો. (CCE 2023)","options":{"A":"300","B":"210","C":"440","D":"240"},"correct_answer":"D","explanation":"વાર્તાના પુસ્તકો = 5 ભાગ = 1200 ⟹ 1 ભાગ = 240.\nઅન્ય પુસ્તકો = 4 ભાગ = 960.\nનવો ગુણોત્તર 3:2 ⟹ અન્ય પુસ્તકો 2 ભાગ = 960 ⟹ 1 ભાગ = 480.\nનવા વાર્તા પુસ્તકો = 3 ભાગ = 3 × 480 = 1440.\nઉમેરેલા પુસ્તકો = 1440 - 1200 = 240."},{"question_number":92,"question_text":"તાંબુ અને ટીનની 960 ગ્રામ મિશ્રધાતુ 7 : 5 ના ગુણોત્તરમાં છે. 7 : 6 નો ગુણોત્તર મેળવવા માટે તેમાં કેટલું ટીન (ગ્રામમાં) ઉમેરવું જોઈએ? (CCE 2023)","options":{"A":"88 ગ્રામ","B":"80 ગ્રામ","C":"92 ગ્રામ","D":"78 ગ્રામ"},"correct_answer":"B","explanation":"કુલ 12 ભાગ = 960 ગ્રામ ⟹ 1 ભાગ = 80 ગ્રામ.\nતાંબુ અચળ (7 ભાગ) રહે છે, ટીનમાં 5 થી વધીને 6 ભાગ (1 ભાગનો વધારો) થાય છે.\nઉમેરેલું ટીન = 1 ભાગ = 80 ગ્રામ."},{"question_number":93,"question_text":"એક લંબચોરસની પહોળાઈ અને લંબાઈ મધ્યમ પ્રમાણપદનો સંબંધ ધરાવે છે જેમાં પહોળાઈ 8 cm છે. જો લંબાઈ એ પહોળાઈ કરતાં ચાર ગણી હોય, તો પહોળાઈ અને લંબાઈ વચ્ચે મધ્યમ પ્રમાણપદનું મૂલ્ય શું હશે? (CCE 2023)","options":{"A":"32 cm","B":"12 cm","C":"16 cm","D":"24 cm"},"correct_answer":"C","explanation":"પહોળાઈ = 8 cm, લંબાઈ = 4 × 8 = 32 cm.\nમધ્યમ પ્રમાણપદ = √(8 × 32) = √256 = 16 cm."},{"question_number":94,"question_text":"સુનંદા પાસે માત્ર ₹1 અને ₹2ના સિક્કા છે. જો તેની પાસે કુલ સિક્કાની સંખ્યા 65 હોય અને એની રકમ ₹75 થાય છે, તો અનુક્રમે ₹1 અને ₹2ના સિક્કાની સંખ્યા શોધો. (CCE 2023)","options":{"A":"55, 10","B":"25, 25","C":"10, 55","D":"20, 30"},"correct_answer":"A","explanation":"ધારો કે ₹2 ના સિક્કા y છે.\n65 + y = 75 ⟹ y = 10 (₹2 ના સિક્કા).\n₹1 ના સિક્કા = 65 - 10 = 55."},{"question_number":95,"question_text":"એક બાળક પાસે 50 પૈસાના સિક્કા અને 1 રૂપિયાના સિક્કા છે. 50 પૈસા અને 1 રૂપિયાના સિક્કાની સંખ્યાનો ગુણોત્તર 6 : 7 છે. જો તેની પાસે Rs. 20 હોય, તો તેની પાસે કેટલા 50 પૈસાના સિક્કા છે? (CCE 2023)","options":{"A":"16","B":"12","C":"10","D":"14"},"correct_answer":"B","explanation":"સિક્કાઓની સંખ્યા 6x અને 7x.\nકુલ મૂલ્ય = 0.50(6x) + 1(7x) = 3x + 7x = 10x = 20 ⟹ x = 2.\n50 પૈસાના સિક્કા = 6x = 6 × 2 = 12."},{"question_number":96,"question_text":"એક બોક્સમાં 5 રૂપિયા, 2 રૂપિયા અને 1 રૂપિયાના સિક્કા છે અને તેમનું કુલ મૂલ્ય અનુક્રમે 10 : 6 : 7 ના ગુણોત્તરમાં છે, જો કુલ 144 સિક્કા હોય, તો બોક્સમાં કેટલા 2 રૂપિયાના સિક્કા હશે? (CCE 2023)","options":{"A":"36","B":"84","C":"24","D":"96"},"correct_answer":"A","explanation":"સિક્કાઓની સંખ્યાનો ગુણોત્તર = (10/5) : (6/2) : (7/1) = 2 : 3 : 7.\nકુલ 12 ભાગ = 144 ⟹ 1 ભાગ = 12.\n2 રૂપિયાના સિક્કા = 3 ભાગ = 3 × 12 = 36."},{"question_number":97,"question_text":"એક બેગમાં 2 રૂપિયા, 5 રૂપિયા અને 10 રૂપિયાના સિક્કાના રૂપમાં Rs.568 હોય છે. 2 રૂપિયા, 5 રૂપિયા અને 10 રૂપિયાના સિક્કાઓની સંખ્યા 6 : 8 : 9 ના ગુણોત્તરમાં છે. બેગમાં સિક્કાઓની કુલ સંખ્યા કેટલી છે? (CCE 2023)","options":{"A":"76","B":"64","C":"92","D":"88"},"correct_answer":"C","explanation":"મૂલ્ય = 2(6x) + 5(8x) + 10(9x) = 12x + 40x + 90x = 142x = 568 ⟹ x = 4.\nકુલ સિક્કા = (6 + 8 + 9)x = 23x = 23 × 4 = 92."},{"question_number":98,"question_text":"A અને B ની માસિક આવક 8 : 7 ના ગુણોત્તરમાં છે અને તેમનો ખર્ચ 19 : 16 ના ગુણોત્તરમાં છે. જો દરેક વ્યક્તિ દર મહિને Rs. 5000 બચાવે છે, તો A ની માસિક આવક કેટલી હશે? (CCE 2023)","options":{"A":"Rs. 26000","B":"Rs. 24000","C":"Rs. 18000","D":"Rs. 20000"},"correct_answer":"B","explanation":"ક્રોસ મલ્ટિપ્લિકેશન ટ્રીક:\n(8 × 16 - 7 × 19) x = (19 - 16) × 5000\n(128 - 133) x = 3 × 5000 ⟹ 5x = 15000 ⟹ x = 3000.\nA ની આવક = 8x = 8 × 3000 = Rs. 24,000."},{"question_number":99,"question_text":"M અને Nની આવકો 4 : 3 ના ગુણોત્તરમાં છે અને તેમના ખર્ચાઓ 3 : 2 ના ગુણોત્તરમાં છે. જો દરેક Rs.100 બચાવે છે, તો M ની આવક કેટલી છે? (CCE 2023)","options":{"A":"Rs. 350","B":"Rs. 600","C":"Rs. 550","D":"Rs. 400"},"correct_answer":"D","explanation":"આવક તફાવત 4 - 3 = 1; ખર્ચ તફાવત 3 - 2 = 1.\n1 ભાગ = 100.\nM ની આવક = 4 ભાગ = 4 × 100 = Rs. 400."},{"question_number":100,"question_text":"બે સંખ્યાઓ વચ્ચેનો ગુણોત્તર 5 : 4 છે. જો દરેક સંખ્યાને 8 જેટલી વધારવામાં આવે, તો ગુણોત્તર 6 : 5 બને છે. તો બંને સંખ્યાઓ વચ્ચેનો તફાવત ______ છે. (CCE 2023)","options":{"A":"8","B":"9","C":"6","D":"4"},"correct_answer":"A","explanation":"તફાવત 6 - 5 = 1 અને 5 - 4 = 1.\n1 ભાગ = 8.\nસંખ્યાઓનો તફાવત = 5 - 4 = 1 ભાગ = 8."},{"question_number":101,"question_text":"બે સંખ્યાઓનો ગુણોત્તર 8 : 5 છે. જો મોટી સંખ્યામાં 8 ઉમેરવામાં આવે અને નાની સંખ્યામાંથી 2 બાદ કરવામાં આવે, તો મોટી સંખ્યા નાની સંખ્યાના ત્રણ ગણી બને છે. તો તે સંખ્યાઓ શોધો. (CCE 2023)","options":{"A":"82/2, 51/2","B":"16, 10","C":"75/6, 41/6","D":"72, 95"},"correct_answer":"B","explanation":"(8x + 8) = 3(5x - 2) ⟹ 8x + 8 = 15x - 6 ⟹ 7x = 14 ⟹ x = 2.\nસંખ્યાઓ: 8(2) = 16 અને 5(2) = 10."},{"question_number":102,"question_text":"H અને I ની આવકનો ગુણોત્તર 21 : 23 છે અને તેમના ખર્ચનો ગુણોત્તર 17 : 19 છે. જો તેઓ દરેક ₹ 8000 બચાવે, તો I ની આવક શોધો. (CCE 2023)","options":{"A":"₹34,000","B":"₹52,000","C":"₹46,000","D":"₹38,000"},"correct_answer":"C","explanation":"આવક અને ખર્ચનો તફાવત: 21 - 17 = 4, 23 - 19 = 4 ભાગ.\n4 ભાગ = 8000 ⟹ 1 ભાગ = 2000.\nI ની આવક = 23 ભાગ = 23 × 2000 = ₹ 46,000."},{"question_number":103,"question_text":"અરમાન અને બિપિનની માસિક આવક 5 : 6 ના ગુણોત્તરમાં છે. તેમના ખર્ચાઓ 3 : 4 ના ગુણોત્તરમાં છે. જો અરમાન દર મહિને Rs. 150 બચાવે છે અને બિપિન દર મહિને Rs. 100 બચાવે છે, તો અરમાનની આવક કેટલી છે? (CCE 2023)","options":{"A":"Rs. 900","B":"Rs. 600","C":"Rs. 1050","D":"Rs. 750"},"correct_answer":"D","explanation":"ક્રોસ મલ્ટિપ્લિકેશન ટ્રીક:\n(5 × 4 - 6 × 3) x = 3 × 100 - 4 × 150\n(20 - 18) x = 600 - 300 ⟹ 2x = 300 ⟹ x = 150.\nઅરમાનની આવક = 5x = 5 × 150 = Rs. 750."},{"question_number":104,"question_text":"P અને Q ની આવક 2 : 1 ના ગુણોત્તરમાં છે અને તેમના ખર્ચાઓ 5 : 2 ના ગુણોત્તરમાં છે. જો દરેક ₹ 500 બચાવે છે, તો Q ની આવક _______ છે. (CCE 2023)","options":{"A":"₹ 800","B":"₹ 1200","C":"₹ 1000","D":"₹ 1500"},"correct_answer":"D","explanation":"ક્રોસ મલ્ટિપ્લિકેશન ટ્રીક:\n(2 × 2 - 1 × 5) x = (5 - 2) × 500\n(4 - 5) x = 3 × 500 ⟹ 1x = 1500.\nQ ની આવક = 1x = ₹ 1500."},{"question_number":105,"question_text":"વેદાંત અને સેમની આવકનો ગુણોત્તર 5 : 6 છે. વેદાંત અને સેમના ખર્ચનો ગુણોત્તર 2 : 3 છે અને દરેક જણ Rs.300 બચાવે છે. વેદાંત અને સેમની આવક શોધો. (CCE 2023)","options":{"A":"Rs 500 અને Rs. 600","B":"Rs. 800 અને Rs. 700","C":"Rs. 750 અને Rs. 400","D":"Rs. 600 અને Rs. 700"},"correct_answer":"A","explanation":"તફાવત 5 - 2 = 3 ભાગ અને 6 - 3 = 3 ભાગ = 300 ⟹ 1 ભાગ = 100.\nવેદાંતની આવક = 5 × 100 = Rs. 500.\nસેમની આવક = 6 × 100 = Rs. 600."}]};
const RATIO_NOTES = [["1. ગુણોત્તર (Ratio) — મૂળભૂત સમજ",["ગુણોત્તર એટલે સમાન એકમ ધરાવતી બે કે તેથી વધુ રાશિઓની ભાગાકારથી સરખામણી. જો A:B = 3:5 હોય, તો Aના 3 ભાગ અને Bના 5 ભાગ છે; તેનો અર્થ A=3 અને B=5 જ છે એવું નહીં—બંને 3k અને 5k પણ હોઈ શકે.","VIS:ratio-bars","§ a:b = a/b અને ગુણોત્તરને સામાન્ય રીતે સૌથી સરળ પૂર્ણાંક સ્વરૂપમાં લખીએ.","## એકમ સરખા કર્યા પછી જ ગુણોત્તર કાઢવો","→ પહેલા બંને રાશિઓને એક જ એકમમાં ફેરવો.","→ પછી પ્રથમ રાશિ : બીજી રાશિ લખો.","→ બંને પદને તેમના મહત્તમ સામાન્ય અવયવથી ભાગીને સાદું કરો.","Q: 3.5 મીટર : 10 સેન્ટીમીટર ⇒ 3.5 m = 350 cm ⇒ 350:10 ⇒ બંનેને 10 વડે ભાગો ⇒ 35:1.","VIS:unit-conversion","★ ગુણોત્તરમાં એકમ લખતા નથી, પરંતુ સરખામણી પહેલાં એકમો સરખા કરવા જરૂરી છે.","⚠ 3.5 m : 10 cm ને સીધું 3.5:10 ન લખવું. 1 m = 100 cm યાદ રાખો."]],["2. સમકક્ષ ગુણોત્તર અને ગુણોત્તરને જોડવાની પદ્ધતિ",["ગુણોત્તરના બંને પદને એક જ સંખ્યાથી ગુણીએ અથવા ભાગીએ તો ગુણોત્તરનું મૂલ્ય બદલાતું નથી. જેમ કે 2:3 = 4:6 = 10:15.","§ a:b = ka:kb (જ્યાં k ≠ 0).","## બે ગુણોત્તરમાં વચ્ચેનું પદ સરખું કરો (Zig-Zag / N પદ્ધતિ)","→ A:B અને B:C આપેલ હોય, તો બંને ગુણોત્તરમાં Bનું મૂલ્ય સમાન બનાવો.","→ સામાન્ય રીતે Bનાં બંને મૂલ્યોનો લ.સા.અ. લો; પછી A:B:C લખો.","Q: A:B = 2:3 અને B:C = 5:6 ⇒ પ્રથમ ગુણોત્તરને 5 વડે ગુણો: 10:15. બીજા ગુણોત્તરને 3 વડે ગુણો: 15:18 ⇒ A:B:C = 10:15:18.","VIS:chain-ratio","## એક કરતાં વધુ ગુણોત્તર","Q: P:Q = 11:3 અને Q:R = 2:3 ⇒ Q માટે 3 અને 2નો લ.સા.અ. 6 લો ⇒ P:Q = 22:6 અને Q:R = 6:9 ⇒ P:Q:R = 22:6:9.","⚠ મધ્ય પદ સરખું કર્યા વગર સીધાં ત્રણ ગુણોત્તરના પદ જોડશો નહીં."]],["3. પ્રમાણ (Proportion) અને Cross Multiplication",["જ્યારે બે ગુણોત્તરો સમાન હોય ત્યારે પ્રમાણ કહેવાય: a:b :: c:d અથવા a/b = c/d.","VIS:proportion-cross","§ a:b :: c:d હોય તો a×d = b×c. આ ક્રોસ ગુણાકારનો મૂળ નિયમ છે.","→ અજ્ઞાત પદ હોય તો પહેલાં ગુણોત્તરને અપૂર્ણાંક સ્વરૂપે લખો.","→ પછી ક્રોસ ગુણાકાર કરો.","→ અજ્ઞાત પદ ધરાવતું સમીકરણ ઉકેલો અને અંતે મૂળ પ્રમાણમાં મૂકી ચકાસો.","Q: 8.25:x :: 3:8 ⇒ 8.25/x = 3/8 ⇒ 3x = 8.25×8 = 66 ⇒ x = 22.","## તૃતીય અને ચતુર્થ પ્રમાણપદ","§ a અને bનું તૃતીય પ્રમાણપદ c = b²/a (a:b = b:c).","§ a,b,cનું ચતુર્થ પ્રમાણપદ d = (b×c)/a (a:b = c:d).","Q: 15, 18, 45નું ચતુર્થ પ્રમાણપદ ⇒ d = (18×45)/15 = 54.","⚠ તૃતીય પ્રમાણપદ અને ચતુર્થ પ્રમાણપદનાં સૂત્રોને એકબીજાની જગ્યાએ ન વાપરવા."]],["4. મધ્યમ પ્રમાણપદ (Mean Proportional)",["a અને c વચ્ચેનું મધ્યમ પ્રમાણપદ b હોય તો a:b = b:c. તેથી b² = a×c અને b = √(a×c) (ધન રાશિઓ માટે ધન વર્ગમૂળ લો).","VIS:mean-proportion","§ મધ્યમ પ્રમાણપદ = √(પ્રથમ પદ × ત્રીજું પદ).","→ પહેલાં બંને સંખ્યાનો ગુણાકાર કરો.","→ શક્ય હોય તો પૂર્ણ વર્ગોમાં વિભાજિત કરો.","→ અંતે વર્ગમૂળ લો.","Q: 196 અને 400નું મધ્યમ પ્રમાણપદ ⇒ √(196×400) = √196×√400 = 14×20 = 280.","Q: 0.02 અને 0.98નું મધ્યમ પ્રમાણપદ ⇒ √(0.02×0.98) = √0.0196 = 0.14.","★ જો મધ્યમ પ્રમાણપદ 9 હોય તો બે પદોનો ગુણાકાર 81 હોવો જરૂરી છે.","⚠ √(a+c) નહીં, √(a×c) લેવાનું છે."]],["5. કુલ રકમ કે સંખ્યાને ગુણોત્તરમાં વહેંચવી",["ગુણોત્તર a:b હોય અને કુલ રકમ T હોય, તો કુલ ભાગ = a+b. એક ભાગ = T/(a+b). પહેલી રકમ = a×એક ભાગ; બીજી રકમ = b×એક ભાગ.","VIS:share-distribution","§ ભાગનું મૂલ્ય = કુલ રકમ ÷ ગુણોત્તરના બધા પદોનો સરવાળો.","Q: ₹45 ને 2:3માં વહેંચો ⇒ કુલ ભાગ 2+3=5 ⇒ એક ભાગ ₹9 ⇒ હિસ્સા ₹18 અને ₹27.","Q: A:B:C = 3:2:5 અને કુલ ₹1860 ⇒ કુલ 10 ભાગ ⇒ એક ભાગ ₹186 ⇒ C = 5×186 = ₹930.","## જ્યારે સરવાળો / તફાવત અપાયેલ હોય","→ સરવાળો આપેલ હોય: કુલ ભાગોનો સરવાળો લો.","→ તફાવત આપેલ હોય: મોટા અને નાના ગુણોત્તર પદનો તફાવત લો.","Q: સંખ્યાઓ 4:9 છે અને તફાવત 675 ⇒ 5 ભાગ = 675 ⇒ એક ભાગ 135 ⇒ નાની સંખ્યા 4×135 = 540.","⚠ જે રકમ પૂછાઈ હોય તે પદ સાથે જોડાયેલ ભાગ જ ગુણવો."]],["6. બીજગણિતીય ગુણોત્તર: સરવાળો, તફાવત અને વર્ગ",["ગુણોત્તર a:b = p:q હોય તો a=pk અને b=qk મૂકો. પછી પ્રશ્નમાં આપેલ સમીકરણમાં મૂકી k શોધો.","VIS:sum-difference","§ જો બે સંખ્યાઓનો સરવાળો S અને તફાવત D હોય: મોટી = (S+D)/2; નાની = (S−D)/2.","Q: સરવાળો 102 અને તફાવત 34 ⇒ મોટી = (102+34)/2 = 68; નાની = (102−34)/2 = 34 ⇒ ગુણોત્તર 2:1.","## વર્ગવાળા પ્રશ્નો","→ ગુણોત્તર p:q હોય તો સંખ્યાઓ pk અને qk તરીકે લખો.","→ વર્ગનો સરવાળો આપેલ હોય તો p²k² + q²k² = આપેલ સરવાળો.","Q: 8:6:3 ગુણોત્તર અને વર્ગોનો સરવાળો 981 ⇒ (64+36+9)k² = 981 ⇒ 109k²=981 ⇒ k²=9 ⇒ k=3.","★ ધન સંખ્યાઓ માટે જ k=√(9)=3 લો; પ્રશ્નમાં ધન સંખ્યા/ધન સંખ્યાઓ છે કે નહીં તે જુઓ.","⚠ k શોધ્યા પછી પાછા મૂળ ગુણોત્તરના દરેક પદમાં k ગુણવાનું ભૂલશો નહીં."]],["7. સિક્કા, મિશ્રણ અને વસ્તુઓની સંખ્યા",["સિક્કાના પ્રશ્નમાં સિક્કાની સંખ્યા અને નાણાકીય મૂલ્ય અલગ છે. કુલ મૂલ્ય = સિક્કાની સંખ્યા × એક સિક્કાનો મૂલ્ય.","VIS:coins-mixtures","§ સિક્કાની સંખ્યા = તે પ્રકારનું કુલ મૂલ્ય ÷ સિક્કાનો મૂલ્યવર્ગ.","Q: ₹1 અને ₹2ના કુલ 65 સિક્કા છે અને કુલ કિંમત ₹75 છે. ₹2ના સિક્કા x હોય તો ₹1ના સિક્કા 65−x. 65−x+2x=75 ⇒ x=10. એટલે ₹2ના 10 અને ₹1ના 55 સિક્કા.","## મિશ્રણમાં એક ઘટક અચળ હોય","→ જે ઘટક ઉમેરાતો નથી/બદલાતો નથી તેને અચળ રાખો.","→ તેની રાશિ પરથી નવા ગુણોત્તરમાં એક ભાગ શોધો.","Q: 7:5નું મિશ્રણ 960 ગ્રામ છે. કુલ 12 ભાગ ⇒ એક ભાગ 80 ગ્રામ. તાંબું 7 ભાગ = 560 ગ્રામ અચળ છે. નવા 7:6 ગુણોત્તરમાં ટીન = 6×80 = 480 ગ્રામ, એટલે ઉમેરવાનું ટીન 480−400 = 80 ગ્રામ.","⚠ ગુણોત્તર સિક્કાની સંખ્યાનો છે કે સિક્કાના કુલ મૂલ્યનો છે—પ્રશ્નમાંથી આ સ્પષ્ટ કરો."]],["8. આવક, ખર્ચ અને બચત — Cross Multiplication Trick",["આવક − ખર્ચ = બચત. બે વ્યક્તિની આવકનો ગુણોત્તર અને ખર્ચનો ગુણોત્તર અલગ હોઈ શકે છે; આવક/ખર્ચ માટે અલગ ગુણાંક રાખો.","VIS:income-expense","§ આવક A:B = p:q હોય તો આવક = px, qx. ખર્ચ C:D = r:s હોય તો ખર્ચ = ry, sy. બચત માટે px−ry = બચત₁ અને qx−sy = બચત₂ લખો.","→ દરેક વ્યક્તિ માટે આવક − ખર્ચ = બચત સમીકરણ બનાવો.","→ બે સમીકરણોમાંથી એક અજ્ઞાત દૂર કરો.","→ પહેલાં આવકનું એકમ/ગુણાંક શોધો, પછી પૂછેલી વ્યક્તિની આવક કાઢો.","Q: આવક 8:7, ખર્ચ 19:16 અને બંનેની બચત ₹5000. 8x−19y=5000 અને 7x−16y=5000. બાદબાકીથી x=3y; પછી 24y−19y=5000 ⇒ y=1000, x=3000. Aની આવક 8x=₹24,000.","⚠ માત્ર આવકના ગુણોત્તર અને ખર્ચના ગુણોત્તરને સીધા બાદ કરી એક જ ભાગ ગણી લેવું દરેક પ્રશ્નમાં યોગ્ય નથી; પહેલા સમીકરણો બનાવો."]],["9. Exam shortcuts અને અંતિમ પુનરાવર્તન",["VIS:quick-sheet","§ a:b = ka:kb  |  a:b::c:d ⇒ ad=bc  |  Mean proportional = √(ac)","§ Third proportional = b²/a  |  Fourth proportional = bc/a  |  ભાગનું મૂલ્ય = કુલ ÷ કુલ ભાગો","## દરેક પ્રશ્ન પહેલાં આ 5 બાબતો તપાસો","→ એકમ સમાન છે કે નહીં?","→ બે પદનો ગુણોત્તર છે કે ત્રણ/ચાર પદનો?","→ સરવાળો, તફાવત, ગુણાકાર કે કુલ રકમમાંથી કઈ માહિતી આપવામાં આવી છે?","→ સામાન્ય મધ્ય પદ સરખું કરવું પડશે?","→ જવાબ પાછો મૂકી ચકાસી શકાય છે?","★ સરળ ગણતરી માટે ગુણોત્તરના પદોનો એકસરખો ગુણાકાર લેવો; સામાન્ય રીતે લ.સા.અ. ઉપયોગી રહે છે.","⚠ દશાંશ, અપૂર્ણાંક, એકમ-ફેરફાર અને શબ્દપ્રશ્નમાં 'શરૂઆતમાં' / 'બાદમાં' જેવા શબ્દો ખાસ ધ્યાનથી વાંચો."]]];
if (typeof NOTES !== "undefined") NOTES.m6 = RATIO_NOTES;

function ratioNoteVisual(kind) {
  const box=(title,body,cls="")=>`<div class="rp-note-visual ${cls}"><div class="rp-visual-title">${title}</div>${body}</div>`;
  const step=(n,title,body)=>`<div class="rp-flow-step"><span>${n}</span><b>${title}</b><small>${body}</small></div>`;
  const bar=(items)=>`<div class="rp-bar-row">${items.map((x,i)=>`<div class="rp-bar-part rp-c${i%4}" style="flex-grow:${Math.max(.5,Number(x.value)||1)}"><b>${x.value}</b><small>${x.label}</small></div>`).join("")}</div>`;
  switch(kind){
    case "ratio-bars": return box("એક ગુણોત્તર એટલે ભાગોની સરખામણી",`<div class="rp-example-label">A : B = 3 : 5</div>${bar([{value:3,label:"A · 3 ભાગ"},{value:5,label:"B · 5 ભાગ"}])}<p class="rp-caption">દરેક ભાગનું મૂલ્ય સરખું છે; સાચી સંખ્યાઓ 3k અને 5k હોઈ શકે.</p>`,"rp-v-purple");
    case "unit-conversion": return box("એકમ બદલો → સરખાવો → સાદું કરો",`<div class="rp-flow">${step("01","3.5 મીટર","એકમ બદલો") }<i>→</i>${step("02","350 cm","3.5 × 100") }<i>→</i>${step("03","350 : 10","બંને cmમાં") }<i>→</i>${step("04","35 : 1","10 વડે ભાગો")}</div><p class="rp-caption">આખી સરખામણીમાં એકમ એકસરખા હોય પછી જ ratio ઘટાડો.</p>`,"rp-v-cyan");
    case "proportion-cross": return box("Cross multiplication — ક્રોસ ગુણાકાર",`<div class="rp-cross"><div class="rp-frac"><b>a</b><i></i><b>b</b></div><span>::</span><div class="rp-frac"><b>c</b><i></i><b>d</b></div></div><div class="rp-equation">a × d = b × c</div><div class="rp-cross-note"><span>a ↘ d</span><span>b ↗ c</span></div><p class="rp-caption">સમાન ગુણોત્તરમાં બાહ્ય પદોનો ગુણાકાર = મધ્ય પદોનો ગુણાકાર.</p>`,"rp-v-cyan");
    case "mean-proportion": return box("મધ્યમ પ્રમાણપદ — બંને બાજુનું સંતુલન",`<div class="rp-equation">a : x = x : c</div><div class="rp-equation rp-answer-equation">x² = a × c <span>⇒</span> x = √(ac)</div><div class="rp-example-label">196 અને 400</div><div class="rp-flow">${step("a","196","√196 = 14") }<i>×</i>${step("c","400","√400 = 20") }<i>→</i>${step("✓","280","14 × 20")}</div>`,"rp-v-purple");
    case "chain-ratio": return box("Zig-Zag / N પદ્ધતિ",`<div class="rp-chain"><div><small>A : B</small><b>2 : 3</b></div><div class="rp-chain-arrows">B સરખું કરો ↘</div><div><small>B : C</small><b>5 : 6</b></div></div><div class="rp-flow">${step("01","10 : 15","પ્રથમને ×5") }<i>+</i>${step("02","15 : 18","બીજાને ×3") }<i>→</i>${step("03","10:15:18","A:B:C")}</div><p class="rp-caption">મધ્ય પદ B બંને બાજુ એકસરખું થયા પછી જ ત્રણ પદનો ratio લખો.</p>`,"rp-v-cyan");
    case "share-distribution": return box("કુલ રકમને ratioમાં વહેંચવી",`<div class="rp-example-label">₹45 ને 2 : 3 માં વહેંચો</div>${bar([{value:2,label:"હિસ્સો 1 · 2"},{value:3,label:"હિસ્સો 2 · 3"}])}<div class="rp-flow">${step("01","કુલ ભાગ = 5","2 + 3") }<i>→</i>${step("02","1 ભાગ = ₹9","45 ÷ 5") }<i>→</i>${step("03","₹18 + ₹27","2×9, 3×9")}</div>`,"rp-v-green");
    case "sum-difference": return box("સરવાળો અને તફાવતથી બે સંખ્યાઓ",`<div class="rp-flow">${step("S","સરવાળો = 102","બંનેનો કુલ") }<i>+</i>${step("D","તફાવત = 34","મોટી − નાની")}</div><div class="rp-equation">મોટી = (S + D) ÷ 2 = 68</div><div class="rp-equation">નાની = (S − D) ÷ 2 = 34</div><p class="rp-caption">ચકાસણી: 68 + 34 = 102 અને 68 − 34 = 34.</p>`,"rp-v-purple");
    case "coins-mixtures": return box("સિક્કા: ગણતરી અને કુલ મૂલ્ય અલગ છે",`<div class="rp-flow">${step("01","સિક્કાની સંખ્યા","x સિક્કા") }<i>×</i>${step("02","મૂલ્યવર્ગ","₹1 / ₹2 / ₹5") }<i>=</i>${step("03","કુલ મૂલ્ય","₹માં જવાબ")}</div><div class="rp-equation">કુલ રૂપિયા = n₁×v₁ + n₂×v₂ + …</div><p class="rp-caption">જો ગુણોત્તર સિક્કાઓની સંખ્યાનો હોય તો દરેક મૂલ્યવર્ગથી ગુણ્યા વગર total value ratio ન કાઢો.</p>`,"rp-v-amber");
    case "income-expense": return box("આવક − ખર્ચ = બચત",`<div class="rp-income-row"><span>આવક</span><div class="rp-income-bar"><i class="rp-income" style="width:100%"></i></div></div><div class="rp-income-row"><span>ખર્ચ</span><div class="rp-income-bar"><i class="rp-expense" style="width:70%"></i></div></div><div class="rp-income-row"><span>બચત</span><div class="rp-income-bar"><i class="rp-saving" style="width:30%"></i></div></div><div class="rp-equation">આવક − ખર્ચ = બચત</div><p class="rp-caption">આવક અને ખર્ચના ગુણોત્તર માટે સામાન્ય રીતે અલગ x અને y લો; પછી બચતનાં સમીકરણો બનાવો.</p>`,"rp-v-green");
    case "quick-sheet": return box("Quick Formula Map",`<div class="rp-formula-grid"><div><small>Proportion</small><b>ad = bc</b></div><div><small>Mean</small><b>√(ac)</b></div><div><small>Third</small><b>b² / a</b></div><div><small>Fourth</small><b>bc / a</b></div><div><small>One part</small><b>Total / Parts</b></div><div><small>Income</small><b>Income − Expense</b></div></div>`,"rp-v-cyan");
    default: return box("Concept Visual",`<div class="rp-equation">ગુણોત્તર → નિયમ → ગણતરી → ચકાસણી</div>`);
  }
}

function rpEsc(x) { return String(x == null ? "" : x).replace(/[&<>\"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])); }
function rpFirstRatio(text) {
  const m=String(text||"").match(/(\d+(?:\.\d+)?)\s*[:：]\s*(\d+(?:\.\d+)?)(?:\s*[:：]\s*(\d+(?:\.\d+)?))?/);
  return m ? m.slice(1).filter(Boolean).map(Number) : [];
}
function rpBars(parts) {
  if(!parts||parts.length<2)return "";
  const names=["A","B","C","D"];
  const max=Math.max(...parts,1);
  return `<div class="rp-ratio-bars">${parts.map((v,i)=>`<div class="rp-rbar"><span class="rp-rlabel">${names[i]} <b>${v}</b></span><div class="rp-rtrack"><i class="rp-c${i%4}" style="width:${Math.max(5,Math.min(100,v/max*100))}%"></i></div></div>`).join("")}</div>`;
}
function rpContextVisual(row, revealAnswer) {
  const n=row.question_number, ratios=rpFirstRatio(row.question_text), result=row.options[row.correct_answer];
  const step=(a,b,c)=>`<div class="rp-flow-step"><span>${a}</span><b>${b}</b><small>${c}</small></div>`;
  let title="પ્રશ્નનો visual model", body="";
  if(n===1){title="એકમ ફેરફારનું visual";body=`<div class="rp-flow">${step("01","3.5 m","× 100") }<i>→</i>${step("02","350 cm","એકમ સમાન") }<i>→</i>${step("03","350 : 10","સરખાવો")}</div>`}
  else if([2,3,4,5,14,15,93].includes(n)){title="મધ્યમ પ્રમાણપદ / square-root model";body=`<div class="rp-equation">a : x = x : c</div><div class="rp-equation rp-answer-equation">x² = a×c ⇒ x = √(ac)</div><p class="rp-caption">પહેલા ગુણાકાર, પછી વર્ગમૂળ; જો x મધ્યમ પદ હોય તો x² = બંને છેડાના પદોનો ગુણાકાર.</p>`}
  else if(n>=6&&n<=17){title="પ્રમાણનો સમીકરણ નકશો";body=`<div class="rp-cross"><div class="rp-frac"><b>a</b><i></i><b>b</b></div><span>::</span><div class="rp-frac"><b>c</b><i></i><b>d</b></div></div><div class="rp-equation">a×d = b×c</div><p class="rp-caption">અજ્ઞાત પદને એક બાજુ રાખીને ઉકેલો.</p>`}
  else if(n>=18&&n<=25){title="Zig-Zag — વચ્ચેનો પદ સરખો કરો";body=`<div class="rp-chain"><div><small>પ્રથમ ગુણોત્તર</small><b>A : B</b></div><div class="rp-chain-arrows">સામાન્ય B સરખું કરો ↘</div><div><small>બીજો ગુણોત્તર</small><b>B : C</b></div></div><div class="rp-equation">A : B : C</div><p class="rp-caption">બંને ગુણોત્તરમાં મધ્ય પદને સમાન બનાવી પછી બાકીના પદ લખો.</p>`}
  else if(n>=26&&n<=47){title="ભાગો મૂકો અને સરળ બનાવો";body=`<div class="rp-equation">a : b = p : q ⇒ a = pk, b = qk</div><div class="rp-equation">આપેલ expressionમાં pk, qk મૂકો</div><p class="rp-caption">દરેક પદમાં એક જ k વપરાય છે; પછી સામાન્ય ગુણાંક કાઢી ratio ઘટાડો.</p>`}
  else if(n>=48&&n<=80){title="ભાગ-મોડેલ (ratio share bar)";body=rpBars(ratios)+`<div class="rp-equation">એક ભાગ = કુલ રકમ ÷ કુલ ratio ભાગો</div><p class="rp-caption">પહેલા ratioનાં બધા પદો ઉમેરો, પછી total ને ભાગોમાં વહેંચો.</p>`}
  else if(n>=81&&n<=88){title="સમીકરણ મોડેલ";body=`<div class="rp-flow">${step("01","સંખ્યા = ratio × k","a = pk, b = qk") }<i>→</i>${step("02","આપેલી શરત","sum / difference / product") }<i>→</i>${step("03","k શોધો","મૂળ સંખ્યાઓ મેળવો")}</div>`}
  else if(n===89||n===90){title="પૈસાની હેરફેર — before/after";body=`<div class="rp-transfer"><div><small>શરૂઆત</small><b>A / S</b><span>− ₹${n===89?"200":"140"}</span></div><i>⇄</i><div><small>બીજી વ્યક્તિ</small><b>R</b><span>શરૂઆતની રકમથી સરખાવો</span></div></div><p class="rp-caption">'શરૂઆતમાં' અને 'બાદમાં'ની રકમ અલગ લખો; પછી totalનું સમીકરણ વાપરો.</p>`}
  else if(n>=91&&n<=97){title="સિક્કા / મિશ્રણ / વધારાનો હિસ્સો";body=`<div class="rp-flow">${step("01","Given ratio","સંખ્યા કે મૂલ્ય? તપાસો") }<i>→</i>${step("02","એક ભાગ શોધો","કુલ / ભાગો") }<i>→</i>${step("03","Target quantity","જરૂરી પદ × ભાગ")}</div><div class="rp-equation">કુલ મૂલ્ય = સંખ્યા × એકમ મૂલ્ય</div>`}
  else {title="આવક–ખર્ચ–બચત મોડેલ";body=`<div class="rp-equation">આવક = ratio × x</div><div class="rp-equation">ખર્ચ = ratio × y</div><div class="rp-equation">આવક − ખર્ચ = બચત</div><p class="rp-caption">બે લોકો માટે બે બચતનાં સમીકરણો બનાવો; પછી x/y શોધો.</p>`}
  return `<div class="rp-visual-card"><div class="rp-visual-title">${title}</div>${body}${revealAnswer?`<div class="rp-answer-strip"><span>સાચો જવાબ</span><b>${rpEsc(result)}</b></div>`:""}</div>`;
}
function rpSolutionHtml(row) {
  let explanation=row.explanation||"આ પ્રશ્ન માટે મૂળ સ્રોતમાં વિગતવાર સમજૂતી ઉપલબ્ધ નથી.";
  const steps=explanation.split(/\n+/).flatMap(line=>line.split(/\s*⟹\s*/).map(x=>x.trim()).filter(Boolean));
  const htmlSteps=steps.map((line,i)=>`<div class="rp-solution-step"><span>${String(i+1).padStart(2,"0")}</span><div>${rpEsc(line)}</div></div>`).join("");
  const takeaway = row.question_number===37 ? "100:2 ને 50:1 સુધી સાદું કરવું જરૂરી છે." : row.question_number===47 ? "c = 7k છે; k=4 હોવાથી c=28." : row.question_number===89 ? "સચિનની નવી રકમ = રવિની શરૂઆતની રકમ; ₹200 ફક્ત એક વાર ટ્રાન્સફર થાય છે." : row.question_number===90 ? "અજયની રકમમાંથી ₹140 બાદની રકમ = રાજુની શરૂઆતની રકમ." : "અંતે મળેલી કિંમતને પ્રશ્નની મૂળ શરત / વિકલ્પ સાથે ચકાસો.";
  return `<div class="rp-solution-intro"><b>ઉકેલને પગથિયે જુઓ</b><span>સૂત્ર → ગણતરી → જવાબ</span></div>${rpContextVisual(row,true)}<div class="rp-solution-steps">${htmlSteps}</div><div class="rp-takeaway"><b>💡 યાદ રાખવાની વાત</b><span>${rpEsc(takeaway)}</span></div>`;
}
function rpQuestionHtml(row) {
  return `<div class="rp-question-intro"><span>CONCEPT VISUAL</span><b>પ્રશ્ન ઉકેલતા પહેલાં આ મોડેલ જુઓ</b></div>${rpContextVisual(row,false)}`;
}
RATIO_PROPORTION_SOURCE.questions.forEach(row=>{
  row.t="x";
  row.q=row.question_text;
  row.o=["A","B","C","D"].map(k=>row.options[k]);
  row.a=["A","B","C","D"].indexOf(row.correct_answer);
  row.y="CCE 2023 · પ્રશ્ન "+row.question_number;
  row.e=row.explanation;
  row.v=rpQuestionHtml(row);
  row.h=rpSolutionHtml(row);
  row.sv=ratioNoteVisual(row.question_number===1?"unit-conversion":row.question_number>=18&&row.question_number<=25?"chain-ratio":row.question_number>=48&&row.question_number<=80?"share-distribution":row.question_number>=91&&row.question_number<=97?"coins-mixtures":row.question_number>=98?"income-expense":"proportion-cross");
});
PYQ.m6 = RATIO_PROPORTION_SOURCE.questions;
